describe('Modal Dialog', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL where the modal can be triggered
        cy.get('.open-modal-button').click(); // Replace with the actual selector to open the modal
    });

    it('should close the modal when clicking on the backdrop (happy path)', () => {
        cy.get('.modal-backdrop').click(); // Replace with the actual selector for the backdrop
        cy.get('.modal').should('not.exist'); // Replace with the actual selector for the modal
    });

    it('should not close the modal when clicking inside the modal', () => {
        cy.get('.modal-content').click(); // Replace with the actual selector for the modal content
        cy.get('.modal').should('exist'); // Ensure the modal is still present
    });
});
